import app.revanced.extension.shared.utils.Utils;import com.google.protobuf.ExtensionRegistryLite;
import com.google.protos.youtube.api.innertube.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.*;import java.io.*;import ultra.downloads.RadioWire;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class GenericRadioTest {
 @Before public void setup(){Utils.testContext=Robolectric.buildActivity(android.app.Activity.class).setup().get();}
 static void var(ByteArrayOutputStream o,long n){while((n&~127L)!=0){o.write((int)n&127|128);n>>>=7;}o.write((int)n);}
 static byte[] f(int n,byte[] v){ByteArrayOutputStream o=new ByteArrayOutputStream();var(o,((long)n<<3)|2);var(o,v.length);o.write(v,0,v.length);return o.toByteArray();}
 static byte[] join(byte[]...all){ByteArrayOutputStream o=new ByteArrayOutputStream();for(byte[] b:all)o.write(b,0,b.length);return o.toByteArray();}
 @Test public void addsSeparateRadioAndPreservesLikedRow()throws Exception{RadioRowTest t=new RadioRowTest();byte[] liked=t.row("VLLM").toByteArray(),other=t.row("VLPLprivate").toByteArray();byte[] input=join(f(1,f(23,liked)),f(1,f(23,other)));byte[] out=RadioWire.transform(input,0x2e6ea0a,UltraRadioBridge.entry().toByteArray());assertFalse(Arrays.equals(input,out));String text=new String(out,"ISO-8859-1");assertTrue(text.contains("Liked music"));assertTrue(text.contains("Radio"));assertTrue(text.indexOf("FEmusic_ultra_radio")<text.indexOf("VLLM"));assertTrue(text.contains("FEmusic_ultra_radio"));assertTrue(text.contains("VLPLprivate"));assertTrue(text.contains(new String(liked,"ISO-8859-1")));assertSame(out,RadioWire.transform(out,0x2e6ea0a,UltraRadioBridge.entry().toByteArray()));}
 @Test public void unrelatedRowAndNullCommandUnchanged()throws Exception{RadioRowTest t=new RadioRowTest();byte[] in=t.row("VLPLprivate").toByteArray();assertSame(in,RadioWire.transform(in,0x2e6ea0a,UltraRadioBridge.entry().toByteArray()));assertSame(in,RadioWire.transform(in,0x2e6ea0a,null));}
 @Test public void isolatedSingularRowNeverReplacesLiked()throws Exception{byte[] in=new RadioRowTest().row("VLLM").toByteArray();assertSame(in,RadioWire.transform(in,0x2e6ea0a,UltraRadioBridge.entry().toByteArray()));}
 @Test public void presenterHookNeverReplacesLiked(){bqtu liked=new RadioRowTest().row("VLLM");assertSame(liked,UltraRadioBridge.row(liked));}
 @Test public void uppercaseLabelAlsoInsertsRadioAndCloneDropsInheritedMenus()throws Exception{bqtu row=new RadioRowTest().row("VLLM");row.e=UltraRadioBridge.text("Liked Music");byte[] input=join(f(1,f(23,join(row.toByteArray(),f(0x3f5caaa,"menu-private-action".getBytes("UTF-8"))))),f(1,f(23,new RadioRowTest().row("VLPLother").toByteArray())));byte[] output=RadioWire.transform(input,0x2e6ea0a,UltraRadioBridge.entry().toByteArray());String text=new String(output,"ISO-8859-1");assertTrue(text.contains("Radio"));assertEquals(text.indexOf("menu-private-action"),text.lastIndexOf("menu-private-action"));}
}
